const CACHE='safeincloud-shell-v6';const FILES=['./','./index.html','./style.css?v=0.3.0','./crypto.js','./app.js?v=0.3.0','./mobile.js?v=0.3.0','./icon.svg','./manifest.json'];self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES))));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k))))));self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==location.origin||!FILES.some(f=>new URL(f,location.href).pathname===u.pathname))return;e.respondWith(fetch(e.request).catch(()=>caches.match(e.request)))})

